/** Joker artwork. In this pack Joker1 is the black joker and Joker2 the red one. */
export const JOKER_FILES = { black: 'Joker1.svg', red: 'Joker2.svg' };

/** The pack ships no card back, so <CardBack /> draws one in SVG. */
export const CARD_BACK_FILE = null;

/** Native artwork size (viewBox 167.09 x 242.67), about 5:7.26. */
export const CARD_ASPECT = 242.667 / 167.087;

export function cardFile(rank, suit, color) {
  if (rank === 'JOKER') return JOKER_FILES[color === 'red' ? 'red' : 'black'] ?? null;
  return CARD_FILES[`${rank}${suit}`] ?? null;
}

export function cardImageUrl(rank, suit, color) {
  const file = cardFile(rank, suit, color);
  return file ? CARD_BASE_URL + file : null;
}

export function allCardImageUrls() {
  return [...Object.values(CARD_FILES), ...Object.values(JOKER_FILES).filter(Boolean)].map((f) => CARD_BASE_URL + f);
}
